-- Urushi: Hyprland visual layer. Generated by rice-render from palette.toml.
hl.config({
    general = {
        gaps_in = {{ shape.gaps_in }}, gaps_out = {{ shape.gaps_out }}, border_size = {{ shape.border }},
        col = {
            active_border   = "{{ colors.gold | hypr(ff) }}",
            inactive_border = "{{ roles.overlay | hypr(ff) }}",
        },
    },
    decoration = {
        rounding = {{ shape.window }}, rounding_power = {{ shape.rounding_power }},
        active_opacity = 1.0, inactive_opacity = {{ opacity.inactive }},
        blur   = { enabled = false },
        shadow = { enabled = true, range = 12, render_power = 4, color = "{{ roles.shadow | hypr(aa) }}" },
    },
    group = {
        col = { border_active = "{{ colors.gold | hypr(ff) }}", border_inactive = "{{ roles.overlay | hypr(ff) }}" },
        groupbar = {
            font_family = "{{ fonts.ui }}", text_color = "{{ roles.fg | hypr(ff) }}",
            col = { active = "{{ roles.accent | hypr(ff) }}", inactive = "{{ roles.surface | hypr(ff) }}" },
        },
    },
    animations = { enabled = true },
})

hl.curve("lacquer", { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} }, { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.animation({ leaf = "windows",    enabled = true, speed = {{ motion.open | div(100) }},      bezier = "lacquer", style = "slide" })
hl.animation({ leaf = "fade",       enabled = true, speed = {{ motion.focus | div(100) }},     bezier = "lacquer" })
hl.animation({ leaf = "border",     enabled = true, speed = {{ motion.focus | div(100) }},     bezier = "lacquer" })
hl.animation({ leaf = "workspaces", enabled = true, speed = {{ motion.workspace | div(100) }}, bezier = "lacquer", style = "slidevert" })
hl.animation({ leaf = "borderangle", enabled = false })

hl.window_rule({ name = "urushi-opaque",     match = { tag = "opaque" },     opacity = "1.0 override 1.0 override" })
hl.window_rule({ name = "urushi-pip",        match = { tag = "pip" },        border_size = 0 })
hl.window_rule({ name = "urushi-fullscreen", match = { fullscreen = true },  border_size = 0, rounding = 0 })
hl.window_rule({ name = "urushi-game",       match = { tag = "game" },       no_anim = true, no_shadow = true, opacity = "1.0 override 1.0 override" })
